 ('re/tools/vector_lib.py',
  '\ndef read_vec(path: pathlib.Path) -> dict:',
  '\n'
  'def _corpus_symbols() -> dict:\n'
  '    """GameState symbols renamed after the corpus was recorded (roadmap S11.4, re/port/corpus_aliases.tsv): old -> new."""\n'
  '    p = ROOT / "re" / "port" / "corpus_aliases.tsv"\n'
  '    if not p.exists():\n'
  '        return {}\n'
  '    rows = [l.split("\\t") for l in p.read_text(encoding="utf-8").splitlines()[1:] if l]\n'
  '    return {r[3]: r[4] for r in rows if r[0] == "global"}\n'
  '\n'
  '\n'
  'def _rename_syms(o, m: dict):\n'
  '    if isinstance(o, dict):\n'
  '        if isinstance(o.get("sym"), str) and o["sym"] in m:\n'
  '            o["sym"] = m[o["sym"]]\n'
  '        for v in o.values():\n'
  '            _rename_syms(v, m)\n'
  '    elif isinstance(o, list):\n'
  '        for v in o:\n'
  '            _rename_syms(v, m)\n'
  '\n'
  '\n'
  'def read_vec(path: pathlib.Path) -> dict:'),
 ('re/tools/vector_lib.py',
  '    validate_doc(doc)\n    return doc',
  '    validate_doc(doc)\n    m = _corpus_symbols()\n    if m:\n        _rename_syms(doc, m)\n    return doc'),
