                         '\n'
                         'The table is re/port/corpus_aliases.tsv (kind, module, addr, corpus_name, port_name): functions by '
                         'their hooks.csv names, GameState\n'
                         'objects by their symbols. A corpus file is never rewritten: its readers translate at the boundary.\n'
                         '"""\n'
                         'from __future__ import annotations\n'
                         '\n'
                         'import csv\n'
                         'import functools\n'
                         'import pathlib\n'
                         '\n'
                         'ROOT = pathlib.Path(__file__).resolve().parents[2]\n'
                         'TABLE = ROOT / "re" / "port" / "corpus_aliases.tsv"\n'
                         '\n'
                         '\n'
                         '@functools.lru_cache(maxsize=None)\n'
                         'def _rows() -> tuple:\n'
                         '    if not TABLE.exists():\n'
                         '        return ()\n'
                         '    with TABLE.open(newline="", encoding="utf-8") as f:\n'
                         '        return tuple(csv.DictReader(f, delimiter="\\t"))\n'
                         '\n'
                         '\n'
                         '@functools.lru_cache(maxsize=None)\n'
                         'def _maps() -> tuple[dict, dict, dict]:\n'
                         '    to_port, to_corpus, syms = {}, {}, {}\n'
                         '    for r in _rows():\n'
                         '        if r["kind"] == "global":\n'
                         '            syms[r["corpus_name"]] = r["port_name"]\n'
                         '        else:\n'
                         '            to_port[r["corpus_name"]] = r["port_name"]\n'
                         '            to_corpus[r["port_name"]] = r["corpus_name"]\n'
                         '    return to_port, to_corpus, syms\n'
                         '\n'
                         '\n'
                         'def port_name(name: str) -> str:\n'
                         '    """The port\'s (registry) name of a function the corpus names `name`."""\n'
                         '    return _maps()[0].get(name, name)\n'
                         '\n'
                         '\n'
                         'def corpus_name(name: str) -> str:\n'
                         '    """The corpus name (.vec stem, raw capture key prefix) of the port function `name`."""\n'
